Procedure BeforeWrite(Cancel, WriteMode, PostingMode) {
    if (WriteMode == DocumentWriteMode.Posting && !ValueIsFilled(Counterparty)) {
        Message("Заповніть контрагента перед проведенням.", StatusMessage.Error);
        Cancel = True;
    }
}

